package br.com.onda;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;
import androidx.media3.common.*;import androidx.media3.session.*;import androidx.media3.session.MediaController;
import com.google.common.util.concurrent.ListenableFuture;import com.google.mlkit.nl.translate.TranslateLanguage;
import java.util.*;import java.util.concurrent.*;
/** Experimental captions from playback PCM, independent of the lyrics catalogue. */
@androidx.media3.common.util.UnstableApi
public class LiveLyricsActivity extends Activity {
 private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService setup=Executors.newSingleThreadExecutor();private Future<?> preparation;private MediaController player;private ListenableFuture<MediaController> connection;private LiveRecognizer recognizer;private LocalLyricTranslator translator;private Button start,stop;private Spinner source,target,model;private TextView status,original,translated;private final List<String> languages=Arrays.asList("en","es","pt","fr","it","de","ja","ko","zh","ru");private final List<String> destinations=new ArrayList<>();private volatile int token;private int caption;private ScrollView scrolling;private boolean visible,requested,ready,attached;private AlertDialog options;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Ui.background(root);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(Ui.dp(this,16),Ui.dp(this,8)+i.getSystemWindowInsetTop(),Ui.dp(this,16),Ui.dp(this,8)+i.getSystemWindowInsetBottom());return i;});setContentView(root);
  Button back=Ui.button(this,"‹ Voltar",v->finish());back.setContentDescription("Voltar da tradução ao vivo");root.addView(back);ScrollView scroll=new ScrollView(this);scrolling=scroll;LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  body.addView(Ui.text(this,"Tradução ao vivo • experimental",24,Ui.TEXT));body.addView(Ui.text(this,"Reconhece o canto a partir do áudio do tocador e das rádios, sem precisar da letra escrita. Não usa microfone nem envia áudio. Pode errar, levar vários segundos e aumentar o consumo. Para ao sair desta tela. Vídeos na página do YouTube não são capturados; use o áudio no tocador.",13,Ui.MUTED));
  Locale display=new Locale("pt","BR");String[] names=new String[languages.size()];for(int i=0;i<names.length;i++)names[i]=new Locale(languages.get(i)).getDisplayLanguage(display);body.addView(Ui.text(this,"Idioma cantado",14,Ui.TEXT));source=new Spinner(this);source.setAdapter(Ui.spinnerLabels(this,names));source.setSelection(Math.max(0,languages.indexOf(getPreferences(0).getString("source","en"))));source.setContentDescription("Idioma cantado no reconhecimento ao vivo");Ui.spinner(source);body.addView(source);
  destinations.addAll(TranslateLanguage.getAllLanguages());destinations.sort(Comparator.comparing(c->new Locale(c).getDisplayLanguage(display)));String[] translatedNames=new String[destinations.size()];for(int i=0;i<translatedNames.length;i++)translatedNames[i]=new Locale(destinations.get(i)).getDisplayLanguage(display);body.addView(Ui.text(this,"Traduzir para",14,Ui.TEXT));target=new Spinner(this);target.setAdapter(Ui.spinnerLabels(this,translatedNames));target.setSelection(Math.max(0,destinations.indexOf(getPreferences(0).getString("target","pt"))));target.setContentDescription("Idioma de destino da tradução ao vivo");Ui.spinner(target);body.addView(target);
  body.addView(Ui.text(this,"Modelo local",14,Ui.TEXT));model=new Spinner(this);String[] models=new String[LiveSpeechModels.Model.values().length];for(int i=0;i<models.length;i++)models[i]=LiveSpeechModels.Model.values()[i].label;model.setAdapter(Ui.spinnerLabels(this,models));model.setSelection(Math.max(0,Math.min(models.length-1,getPreferences(0).getInt("model",0))));model.setContentDescription("Modelo do reconhecimento de canto");Ui.spinner(model);body.addView(model);
  status=Ui.text(this,"Toque em Iniciar com uma música ou rádio já tocando. O reconhecimento usa trechos de 8 segundos.",14,Ui.CYAN);status.setContentDescription("Estado da tradução ao vivo");body.addView(status);body.addView(Ui.text(this,"Canto reconhecido automaticamente • pode conter erros",12,Ui.MUTED));original=Ui.text(this,"O canto reconhecido aparecerá aqui.",21,Ui.TEXT);original.setTextIsSelectable(true);original.setContentDescription("Canto reconhecido ao vivo");body.addView(original);body.addView(Ui.text(this,"Tradução automática",12,Ui.MUTED));translated=Ui.text(this,"A tradução aparecerá aqui.",21,Ui.CYAN);translated.setTextIsSelectable(true);translated.setContentDescription("Tradução do canto ao vivo");body.addView(translated);
  ImageView badge=new ImageView(this);badge.setImageResource(R.drawable.google_translation_attribution);badge.setScaleType(ImageView.ScaleType.CENTER_INSIDE);badge.setContentDescription("powered by Google Translate");body.addView(badge,new LinearLayout.LayoutParams(Ui.dp(this,190),Ui.dp(this,30)));
  LinearLayout controls=new LinearLayout(this);start=Ui.button(this,"Iniciar",v->chooseStart());start.setContentDescription("Iniciar reconhecimento e tradução do canto");stop=Ui.button(this,"Parar",v->{halt();status.setText("Reconhecimento parado. A reprodução foi mantida.");});stop.setContentDescription("Parar reconhecimento mantendo a música");stop.setEnabled(false);controls.addView(start,new LinearLayout.LayoutParams(0,-2,1));controls.addView(stop,new LinearLayout.LayoutParams(0,-2,1));root.addView(controls);
  connection=new MediaController.Builder(this,new SessionToken(this,new ComponentName(this,PlaybackService.class))).buildAsync();connection.addListener(()->{if(isDestroyed())return;try{player=connection.get();player.addListener(new Player.Listener(){@Override public void onEvents(Player p,Player.Events e){if(!visible)return;if(e.contains(Player.EVENT_MEDIA_ITEM_TRANSITION)||e.contains(Player.EVENT_POSITION_DISCONTINUITY)){caption++;if(recognizer!=null)recognizer.reset();original.setText("Ouvindo o novo trecho…");translated.setText("Aguardando reconhecimento…");}attach();}});attach();}catch(Exception e){status.setText("Não foi possível conectar ao tocador.");}},main::post);
 }
 private void chooseStart(){if(player==null||!player.isPlaying()){status.setText("Inicie uma música ou rádio no tocador do Onda e volte a esta tela.");return;}String from=languages.get(source.getSelectedItemPosition()),to=destinations.get(target.getSelectedItemPosition());if(from.equals(to)){status.setText("Escolha idiomas diferentes para traduzir.");return;}LiveSpeechModels.Model chosen=LiveSpeechModels.Model.values()[model.getSelectedItemPosition()];String note="Primeiro uso: reconhecimento "+chosen.label+" e idiomas do tradutor (~30 MB por idioma). Depois funciona localmente, sem cobrança por uso. A precisão e o atraso variam por voz, instrumentos e aparelho.\n\nA música continuará tocando.";options=new AlertDialog.Builder(this).setTitle("Preparar tradução ao vivo").setMessage(note).setPositiveButton("Wi-Fi",(d,w)->begin(chosen,from,to,true)).setNeutralButton("Dados móveis",(d,w)->begin(chosen,from,to,false)).setNegativeButton("Cancelar",null).show();}
 private void begin(LiveSpeechModels.Model chosen,String from,String to,boolean wifi){halt();ActivityManager.MemoryInfo memory=new ActivityManager.MemoryInfo();((ActivityManager)getSystemService(ACTIVITY_SERVICE)).getMemoryInfo(memory);if(memory.lowMemory||memory.availMem<(chosen==LiveSpeechModels.Model.SMALL?500L:250L)*1024*1024){status.setText("Memória livre insuficiente para este modelo. Feche outros apps ou use o modelo Equilibrado. A reprodução foi mantida.");return;}requested=true;final int id=token;start.setEnabled(false);stop.setEnabled(true);source.setEnabled(false);target.setEnabled(false);model.setEnabled(false);getPreferences(0).edit().putString("source",from).putString("target",to).putInt("model",chosen.ordinal()).apply();status.setText("Preparando modelo local…");preparation=setup.submit(()->{try{java.io.File file=LiveSpeechModels.obtain(getApplicationContext(),chosen,wifi,()->id!=token||Thread.currentThread().isInterrupted(),(bytes,total)->main.post(()->{if(id==token&&visible)status.setText("Baixando reconhecimento: "+(bytes*100/total)+"%");}));main.post(()->{if(id!=token||!visible)return;status.setText("Preparando idiomas do tradutor…");try{translator=new LocalLyricTranslator(from,to);translator.prepare(wifi,()->openRecognizer(file,from,id),e->failure(id,e));}catch(Exception e){failure(id,e);}});}catch(Exception e){main.post(()->failure(id,e));}});}
 private void openRecognizer(java.io.File file,String language,int id){if(id!=token||!visible)return;recognizer=new LiveRecognizer(file,language,Math.min(2,Runtime.getRuntime().availableProcessors()),new LiveRecognizer.Listener(){public void ready(){main.post(()->{if(id!=token||!visible)return;ready=true;attach();scrolling.post(()->{if(id==token&&visible)scrolling.smoothScrollTo(0,status.getTop());});});}public void text(String text,long audioMs,long processingMs,int epoch){main.post(()->{if(id!=token||!visible||recognizer==null||epoch!=recognizer.epoch())return;int serial=++caption;if(text.isEmpty()){original.setText("Nenhum canto reconhecido neste trecho.");translated.setText("Aguardando um trecho reconhecível.");status.setText("Canto não reconhecido neste trecho. Instrumentos e vozes misturadas podem dificultar a leitura.");return;}original.setText(text);translated.setText("Traduzindo…");status.setText("Trecho reconhecido • processamento: "+String.format(new Locale("pt","BR"),"%.1f s",processingMs/1000.0)+" • há atraso em relação ao áudio");translator.translate(text,new LyricTranslation.Result(){public void success(String value){if(id==token&&serial==caption&&visible)translated.setText(value);}public void failure(Exception e){if(id==token&&serial==caption&&visible)translated.setText("Não foi possível traduzir este trecho. O canto reconhecido foi mantido.");}});});}public void error(Throwable e){main.post(()->failure(id,e));}});}
 private void attach(){if(!requested||!ready||recognizer==null)return;boolean playing=visible&&player!=null&&player.isPlaying();if(playing&&!attached){recognizer.reset();LiveAudioTap.receiver=recognizer;attached=true;status.setText("Ouvindo o áudio do tocador… aguardando um trecho de 8 segundos.");}else if(!playing&&attached){if(LiveAudioTap.receiver==recognizer)LiveAudioTap.receiver=null;attached=false;recognizer.reset();caption++;status.setText("Reprodução pausada • reconhecimento aguardando.");}}
 private void failure(int id,Throwable error){if(id!=token||!visible)return;halt();String detail=error.getMessage();status.setText("Não foi possível iniciar o reconhecimento. "+(detail==null?"Tente um modelo mais leve ou libere memória.":detail)+" A música foi mantida.");}
 private void halt(){token++;caption++;requested=ready=attached=false;if(preparation!=null){preparation.cancel(true);preparation=null;}if(recognizer!=null){recognizer.close();recognizer=null;}if(translator!=null){translator.close();translator=null;}if(start!=null){start.setEnabled(true);stop.setEnabled(false);source.setEnabled(true);target.setEnabled(true);model.setEnabled(true);}}
 @Override protected void onResume(){super.onResume();visible=true;}
 @Override protected void onPause(){visible=false;boolean was=requested;halt();if(was)status.setText("Reconhecimento encerrado ao sair da tela. Toque em Iniciar para usar novamente.");super.onPause();}
 @Override public void finish(){halt();super.finish();}
 @Override protected void onStop(){visible=false;boolean was=requested;halt();if(was)status.setText("Reconhecimento encerrado ao sair da tela. Toque em Iniciar para usar novamente.");super.onStop();}
 @Override protected void onDestroy(){halt();if(options!=null)options.dismiss();setup.shutdownNow();main.removeCallbacksAndMessages(null);if(connection!=null)MediaController.releaseFuture(connection);super.onDestroy();}
}
